import FormModal from 'flarum/common/components/FormModal';
import Button from 'flarum/common/components/Button';
import { errorText, jsonApi, savedFilters, t } from './util';
/** Name the current filters; admins can share them with every staff member. */
export default class SaveFilterModal extends FormModal {
  name = '';
  shared = false;
  error = null;
  className() {
    return 'MemberDeskSaveFilter Modal--small';
  }
  title() {
    return t('filters.save_title');
  }
  content() {
    return m("div", {
      className: "Modal-body"
    }, this.error ? m("p", {
      className: "MemberDesk-error"
    }, this.error) : null, m("div", {
      className: "Form-group"
    }, m("label", {
      for: "md-filter-name"
    }, t('filters.name')), m("input", {
      id: "md-filter-name",
      className: "FormControl",
      maxlength: 80,
      value: this.name,
      oninput: e => this.name = e.target.value
    })), this.attrs.isAdmin ? m("div", {
      className: "Form-group"
    }, m("label", {
      className: "checkbox"
    }, m("input", {
      type: "checkbox",
      checked: this.shared,
      onchange: e => this.shared = e.target.checked
    }), t('filters.share'))) : null, m("div", {
      className: "Form-group"
    }, m(Button, {
      type: "submit",
      className: "Button Button--primary Button--block",
      loading: this.loading,
      disabled: !this.name.trim()
    }, t('filters.save_button'))));
  }
  onsubmit(e) {
    e.preventDefault();
    this.loading = true;
    jsonApi('POST', 'member-desk-filters', {
      name: this.name.trim(),
      shared: this.shared,
      query: this.attrs.query
    }).then(() => savedFilters()).then(filters => {
      this.attrs.onSaved(filters);
      this.hide();
    }).catch(err => {
      this.error = errorText(err);
      this.loading = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-member-desk', 'common/SaveFilterModal', SaveFilterModal);